artifacts.solve_py:
import os
import sys
import csv
import json
import math

from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
OUT_DIR = "/app/submissions"
SOLUTION_PATH = os.path.join(OUT_DIR, "solution.csv")

CHEM = ["lfp", "nmc"]


def read_csv(name):
    with open(os.path.join(DATA_DIR, name), newline="") as f:
        return list(csv.DictReader(f))


def main():
    os.makedirs(OUT_DIR, exist_ok=True)

    with open(os.path.join(DATA_DIR, "config.json")) as f:
        cfg = json.load(f)

    carbon_price = float(cfg["carbon_price_per_kg"])
    carbon_cap = float(cfg["carbon_cap_kg"])
    tol = float(cfg.get("feasibility_tolerance", 1e-4))

    markets = read_csv("markets.csv")
    hubs = read_csv("collection_hubs.csv")
    tests = read_csv("testing_centers.csv")
    outlets = read_csv("outlets.csv")
    policy = read_csv("policy_rules.csv")
    lanes = read_csv("lanes.csv")

    M = [m["market_id"] for m in markets]
    H = [h["hub_id"] for h in hubs]
    T = [t["test_id"] for t in tests]
    O = [o["outlet_id"] for o in outlets]

    mdata = {}
    for m in markets:
        mid = m["market_id"]
        mdata[mid] = {
            "lfp": float(m["lfp_packs"]),
            "nmc": float(m["nmc_packs"]),
            "d_lfp": float(m["damaged_lfp_share"]),
            "d_nmc": float(m["damaged_nmc_share"]),
            "trace": float(m["traceability_score"]),
            "aud": float(m["min_audited_test_share"]),
        }

    hdata = {}
    for h in hubs:
        hid = h["hub_id"]
        hdata[hid] = {
            "fixed": float(h["fixed_cost"]),
            "fem": float(h["fixed_emission_kg"]),
            "cap": float(h["capacity_packs"]),
            "min": float(h["min_throughput_if_open"]),
            "hcost": float(h["handling_cost_per_pack"]),
            "hem": float(h["handling_emission_kg_per_pack"]),
            "nmc": int(h["nmc_certified"]),
        }

    tdata = {}
    for t in tests:
        tid = t["test_id"]
        tdata[tid] = {
            "fixed": float(t["fixed_cost"]),
            "fem": float(t["fixed_emission_kg"]),
            "cap": float(t["capacity_packs"]),
            "min": float(t["min_throughput_if_open"]),
            "tcost": float(t["test_cost_per_pack"]),
            "tem": float(t["test_emission_kg_per_pack"]),
            "audit": int(t["audit_upgrade"]),
            "reman": int(t["reman_certified"]),
        }

    odata = {}
    for o in outlets:
        oid = o["outlet_id"]
        odata[oid] = {
            "type": o["outlet_type"],
            "tech": o["technology"],
            "cap": float(o["capacity_packs"]),
            "pc_lfp": float(o["processing_cost_lfp"]),
            "pc_nmc": float(o["processing_cost_nmc"]),
            "rv_lfp": float(o["recovered_value_lfp"]),
            "rv_nmc": float(o["recovered_value_nmc"]),
            "pe_lfp": float(o["processing_emission_lfp"]),
            "pe_nmc": float(o["processing_emission_nmc"]),
            "lfp": int(o["lfp_allowed"]),
            "nmc": int(o["nmc_allowed"]),
        }

    pdata = {}
    for p in policy:
        c = p["chemistry"]
        pdata[c] = {
            "hv": float(p["min_high_value_share"]),
            "sl": float(p["min_second_life_share"]),
            "rec": float(p["min_recycle_share"]),
            "disp": float(p["max_disposal_share"]),
            "hydro": float(p["min_hydromet_share_of_recycling"]),
            "pyro": float(p["max_pyromet_share_of_recycling"]),
        }

    # Outlet type sets
    O_reman = {oid for oid in O if odata[oid]["type"] == "remanufacturing"}
    O_2nd = {oid for oid in O if odata[oid]["type"] == "second_life"}
    O_rec = {oid for oid in O if odata[oid]["type"] == "recycler"}
    O_disp = {oid for oid in O if odata[oid]["type"] == "disposal"}
    O_hydro = {oid for oid in O if odata[oid]["tech"] in ("hydromet", "low_temp_hydromet")}
    O_pyro = {oid for oid in O if odata[oid]["tech"] == "pyromet"}

    # Lanes
    lane1 = {}  # (m,h) -> dict
    lane2 = {}  # (h,t) -> dict
    lane3 = {}  # (t,o) -> dict
    for L in lanes:
        stage = L["stage"]
        frm = L["from_id"]
        to = L["to_id"]
        d = float(L["distance_km"])
        cap = float(L["capacity_packs"])
        cpk = float(L["cost_per_pack_km"])
        epk = float(L["emission_kg_per_pack_km"])
        lfp = int(L["lfp_allowed"])
        nmc = int(L["nmc_allowed"])
        rec = {"dist": d, "cap": cap, "cpk": cpk, "epk": epk, "lfp": lfp, "nmc": nmc}
        if stage == "market_to_hub":
            lane1[(frm, to)] = rec
        elif stage == "hub_to_test":
            lane2[(frm, to)] = rec
        elif stage == "test_to_outlet":
            lane3[(frm, to)] = rec

    # Build model
    model = Model("ev_battery_recycling")
    model.setMinimize()

    # Time limit
    tl = 300.0
    env_tl = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env_tl:
        try:
            tl = min(tl, float(env_tl))
        except Exception:
            pass
    model.setRealParam("limits/time", tl)
    model.setRealParam("gap/rel", 0.0005)

    # Binary open vars
    y = {}
    for h in H:
        y[h] = model.addVar(name=f"y_{h}", vtype="B", lb=0.0, ub=1.0, obj=hdata[h]["fixed"])
    z = {}
    for t in T:
        z[t] = model.addVar(name=f"z_{t}", vtype="B", lb=0.0, ub=1.0, obj=tdata[t]["fixed"])

    # Flow vars
    x1 = {}
    for m in M:
        for h in H:
            for c in CHEM:
                L = lane1.get((m, h))
                if L is None:
                    continue
                if c == "lfp" and not L["lfp"]:
                    continue
                if c == "nmc" and not L["nmc"]:
                    continue
                if c == "nmc" and not hdata[h]["nmc"]:
                    continue
                obj = L["cpk"] * L["dist"] + hdata[h]["hcost"]
                x1[(m, h, c)] = model.addVar(name=f"x1_{m}_{h}_{c}", vtype="C", lb=0.0, ub=mdata[m][c], obj=obj)

    x2 = {}
    for h in H:
        for t in T:
            L = lane2.get((h, t))
            if L is None:
                continue
            for m in M:
                for c in CHEM:
                    if c == "lfp" and not L["lfp"]:
                        continue
                    if c == "nmc" and not L["nmc"]:
                        continue
                    if c == "nmc" and not hdata[h]["nmc"]:
                        continue
                    obj = L["cpk"] * L["dist"] + tdata[t]["tcost"]
                    x2[(h, t, m, c)] = model.addVar(name=f"x2_{h}_{t}_{m}_{c}", vtype="C", lb=0.0, ub=mdata[m][c], obj=obj)

    x3 = {}
    for t in T:
        for o in O:
            L = lane3.get((t, o))
            if L is None:
                continue
            for m in M:
                for c in CHEM:
                    if c == "lfp" and not L["lfp"]:
                        continue
                    if c == "nmc" and not L["nmc"]:
                        continue
                    if c == "lfp" and not odata[o]["lfp"]:
                        continue
                    if c == "nmc" and not odata[o]["nmc"]:
                        continue
                    if o in O_reman and not tdata[t]["reman"]:
                        continue
                    if o in O_reman and mdata[m]["trace"] < 0.70 and not tdata[t]["audit"]:
                        continue
                    pc = odata[o]["pc_lfp"] if c == "lfp" else odata[o]["pc_nmc"]
                    rv = odata[o]["rv_lfp"] if c == "lfp" else odata[o]["rv_nmc"]
                    obj = L["cpk"] * L["dist"] + pc - rv
                    x3[(t, o, m, c)] = model.addVar(name=f"x3_{t}_{o}_{m}_{c}", vtype="C", lb=0.0, ub=mdata[m][c], obj=obj)

    # Carbon charge: add to objective via setObjective with emission terms
    # Emission terms:
    # fixed facility: sum_h fem_h y_h + sum_t fem_t z_t
    # transport: sum over lanes epk*dist * flow
    # handling: sum_h hem_h * x1
    # testing: sum_t tem_t * x2
    # processing: sum_o pe * x3
    # We add carbon_price * each emission term to the objective.

    carb_terms = []
    for h in H:
        carb_terms.append(carbon_price * hdata[h]["fem"] * y[h])
    for t in T:
        carb_terms.append(carbon_price * tdata[t]["fem"] * z[t])
    for (m, h, c), v in x1.items():
        L = lane1[(m, h)]
        carb_terms.append(carbon_price * (L["epk"] * L["dist"] + hdata[h]["hem"]) * v)
    for (h, t, m, c), v in x2.items():
        L = lane2[(h, t)]
        carb_terms.append(carbon_price * (L["epk"] * L["dist"] + tdata[t]["tem"]) * v)
    for (t, o, m, c), v in x3.items():
        L = lane3[(t, o)]
        pe = odata[o]["pe_lfp"] if c == "lfp" else odata[o]["pe_nmc"]
        carb_terms.append(carbon_price * (L["epk"] * L["dist"] + pe) * v)

    # Build full objective expression
    obj_expr = quicksum(v.obj for v in list(y.values()) + list(z.values()) + list(x1.values()) + list(x2.values()) + list(x3.values()))
    obj_expr += quicksum(carb_terms)
    model.setObjective(obj_expr, "minimize")

    # Carbon cap constraint (raw emissions, not charged)
    em_terms = []
    for h in H:
        em_terms.append(hdata[h]["fem"] * y[h])
    for t in T:
        em_terms.append(tdata[t]["fem"] * z[t])
    for (m, h, c), v in x1.items():
        L = lane1[(m, h)]
        em_terms.append((L["epk"] * L["dist"] + hdata[h]["hem"]) * v)
    for (h, t, m, c), v in x2.items():
        L = lane2[(h, t)]
        em_terms.append((L["epk"] * L["dist"] + tdata[t]["tem"]) * v)
    for (t, o, m, c), v in x3.items():
        L = lane3[(t, o)]
        pe = odata[o]["pe_lfp"] if c == "lfp" else odata[o]["pe_nmc"]
        em_terms.append((L["epk"] * L["dist"] + pe) * v)
    model.addCons(quicksum(em_terms) <= carbon_cap, name="carbon_cap")

    # (1) Market supply
    for m in M:
        for c in CHEM:
            model.addCons(quicksum(x1[(m, h, c)] for h in H if (m, h, c) in x1) == mdata[m][c], name=f"supply_{m}_{c}")

    # (2) Hub flow conservation per market, chemistry
    for h in H:
        for m in M:
            for c in CHEM:
                if (m, h, c) not in x1:
                    continue
                model.addCons(
                    quicksum(x2[(h, t, m, c)] for t in T if (h, t, m, c) in x2) == x1[(m, h, c)],
                    name=f"hubcons_{h}_{m}_{c}",
                )

    # (3) Testing-center flow conservation per market, chemistry
    for t in T:
        for m in M:
            for c in CHEM:
                inflow = quicksum(x2[(h, t, m, c)] for h in H if (h, t, m, c) in x2)
                if inflow == 0:
                    continue
                model.addCons(
                    quicksum(x3[(t, o, m, c)] for o in O if (t, o, m, c) in x3) == inflow,
                    name=f"testcons_{t}_{m}_{c}",
                )

    # (5) Lane capacities
    for (m, h), L in lane1.items():
        model.addCons(
            quicksum(x1[(m, h, c)] for c in CHEM if (m, h, c) in x1) <= L["cap"],
            name=f"lane1_{m}_{h}",
        )
    for (h, t), L in lane2.items():
        model.addCons(
            quicksum(x2[(h, t, m, c)] for m in M for c in CHEM if (h, t, m, c) in x2) <= L["cap"],
            name=f"lane2_{h}_{t}",
        )
    for (t, o), L in lane3.items():
        model.addCons(
            quicksum(x3[(t, o, m, c)] for m in M for c in CHEM if (t, o, m, c) in x3) <= L["cap"],
            name=f"lane3_{t}_{o}",
        )

    # (6) Hub open/capacity/min
    for h in H:
        model.addCons(
            quicksum(x1[(m, h, c)] for m in M for c in CHEM if (m, h, c) in x1) <= hdata[h]["cap"] * y[h],
            name=f"hubcap_{h}",
        )
        model.addCons(
            quicksum(x1[(m, h, c)] for m in M for c in CHEM if (m, h, c) in x1) >= hdata[h]["min"] * y[h],
            name=f"hubmin_{h}",
        )

    # (7) Test open/capacity/min
    for t in T:
        model.addCons(
            quicksum(x2[(h, t, m, c)] for h in H for m in M for c in CHEM if (h, t, m, c) in x2) <= tdata[t]["cap"] * z[t],
            name=f"testcap_{t}",
        )
        model.addCons(
            quicksum(x2[(h, t, m, c)] for h in H for m in M for c in CHEM if (h, t, m, c) in x2) >= tdata[t]["min"] * z[t],
            name=f"testmin_{t}",
        )

    # (11) Audited-testing share per market, chemistry
    for m in M:
        for c in CHEM:
            aud_in = quicksum(
                x2[(h, t, m, c)] for h in H for t in T if tdata[t]["audit"] == 1 and (h, t, m, c) in x2
            )
            model.addCons(aud_in >= mdata[m]["aud"] * mdata[m][c], name=f"audit_{m}_{c}")

    # (12) Damaged cap on high-value channels per market, chemistry
    for m in M:
        for c in CHEM:
            hv = quicksum(
                x3[(t, o, m, c)] for t in T for o in (O_reman | O_2nd) if (t, o, m, c) in x3
            )
            dshare = mdata[m]["d_lfp"] if c == "lfp" else mdata[m]["d_nmc"]
            model.addCons(hv <= (1.0 - dshare) * mdata[m][c], name=f"damaged_{m}_{c}")

    # (13) Outlet capacity
    for o in O:
        model.addCons(
            quicksum(x3[(t, o, m, c)] for t in T for m in M for c in CHEM if (t, o, m, c) in x3) <= odata[o]["cap"],
            name=f"outletcap_{o}",
        )

    # (14) Chemistry policy rules
    for c in CHEM:
        tot = sum(mdata[m][c] for m in M)
        p = pdata[c]

        hv_c = quicksum(x3[(t, o, m, c)] for t in T for m in M for o in (O_reman | O_2nd) if (t, o, m, c) in x3)
        sl_c = quicksum(x3[(t, o, m, c)] for t in T for m in M for o in O_2nd if (t, o, m, c) in x3)
        rec_c = quicksum(x3[(t, o, m, c)] for t in T for m in M for o in O_rec if (t, o, m, c) in x3)
        disp_c = quicksum(x3[(t, o, m, c)] for t in T for m in M for o in O_disp if (t, o, m, c) in x3)
        hydro_c = quicksum(x3[(t, o, m, c)] for t in T for m in M for o in O_hydro if (t, o, m, c) in x3)
        pyro_c = quicksum(x3[(t, o, m, c)] for t in T for m in M for o in O_pyro if (t, o, m, c) in x3)

        model.addCons(hv_c >= p["hv"] * tot, name=f"policy_hv_{c}")
        model.addCons(sl_c >= p["sl"] * tot, name=f"policy_sl_{c}")
        model.addCons(rec_c >= p["rec"] * tot, name=f"policy_rec_{c}")
        model.addCons(disp_c <= p["disp"] * tot, name=f"policy_disp_{c}")
        model.addCons(hydro_c >= p["hydro"] * rec_c, name=f"policy_hydro_{c}")
        model.addCons(pyro_c <= p["pyro"] * rec_c, name=f"policy_pyro_{c}")

    # Solve
    model.optimize()

    status = model.getStatus()
    print(f"Solver status: {status}")
    if status not in ("optimal", "gap", "timelimit"):
        # try to still get a solution if feasible
        pass

    if model.getNsolns() == 0:
        print("No feasible solution found.")
        sys.exit(1)

    objval = model.getObjval()
    print(f"Objective value: {objval}")

    # Extract solution
    def val(v):
        return model.getVal(v)

    # Write solution.csv
    rows = []
    for h in H:
        if val(y[h]) > 0.5:
            rows.append(["open", "collection_hub", h, "", "", "", "1"])
    for t in T:
        if val(z[t]) > 0.5:
            rows.append(["open", "testing_center", t, "", "", "", "1"])

    for (m, h, c), v in x1.items():
        q = round(val(v), 8)
        if q > tol:
            rows.append(["flow", "market_to_hub", m, h, m, c, f"{q:.8f}"])
    for (h, t, m, c), v in x2.items():
        q = round(val(v), 8)
        if q > tol:
            rows.append(["flow", "hub_to_test", h, t, m, c, f"{q:.8f}"])
    for (t, o, m, c), v in x3.items():
        q = round(val(v), 8)
        if q > tol:
            rows.append(["flow", "test_to_outlet", t, o, m, c, f"{q:.8f}"])

    with open(SOLUTION_PATH, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["record_type", "stage", "origin_id", "destination_id", "market_id", "chemistry", "quantity"])
        for r in rows:
            w.writerow(r)

    print(f"Wrote {len(rows)} rows to {SOLUTION_PATH}")

    # Validation summary
    print("=== Validation ===")
    # Check supply
    for m in M:
        for c in CHEM:
            s = sum(val(x1[(m, h, c)]) for h in H if (m, h, c) in x1)
            assert abs(s - mdata[m][c]) < 1e-4, f"Supply mismatch {m} {c}: {s} vs {mdata[m][c]}"
    print("Supply: OK")

    # Check carbon
    total_em = 0.0
    for h in H:
        total_em += hdata[h]["fem"] * val(y[h])
    for t in T:
        total_em += tdata[t]["fem"] * val(z[t])
    for (m, h, c), v in x1.items():
        L = lane1[(m, h)]
        total_em += (L["epk"] * L["dist"] + hdata[h]["hem"]) * val(v)
    for (h, t, m, c), v in x2.items():
        L = lane2[(h, t)]
        total_em += (L["epk"] * L["dist"] + tdata[t]["tem"]) * val(v)
    for (t, o, m, c), v in x3.items():
        L = lane3[(t, o)]
        pe = odata[o]["pe_lfp"] if c == "lfp" else odata[o]["pe_nmc"]
        total_em += (L["epk"] * L["dist"] + pe) * val(v)
    print(f"Total emissions: {total_em:.4f} (cap {carbon_cap})")
    assert total_em <= carbon_cap + 1e-4, "Carbon cap violated"
    print("Carbon cap: OK")

    # Policy check
    for c in CHEM:
        tot = sum(mdata[m][c] for m in M)
        p = pdata[c]
        hv_c = sum(val(x3[(t, o, m, c)]) for t in T for m in M for o in (O_reman | O_2nd) if (t, o, m, c) in x3)
        sl_c = sum(val(x3[(t, o, m, c)]) for t in T for m in M for o in O_2nd if (t, o, m, c) in x3)
        rec_c = sum(val(x3[(t, o, m, c)]) for t in T for m in M for o in O_rec if (t, o, m, c) in x3)
        disp_c = sum(val(x3[(t, o, m, c)]) for t in T for m in M for o in O_disp if (t, o, m, c) in x3)
        hydro_c = sum(val(x3[(t, o, m, c)]) for t in T for m in M for o in O_hydro if (t, o, m, c) in x3)
        pyro_c = sum(val(x3[(t, o, m, c)]) for t in T for m in M for o in O_pyro if (t, o, m, c) in x3)
        print(f"{c}: hv={hv_c/tot:.4f} (>= {p['hv']}), sl={sl_c/tot:.4f} (>= {p['sl']}), rec={rec_c/tot:.4f} (>= {p['rec']}), disp={disp_c/tot:.4f} (<= {p['disp']}), hydro/rec={hydro_c/max(rec_c,1e-9):.4f} (>= {p['hydro']}), pyro/rec={pyro_c/max(rec_c,1e-9):.4f} (<= {p['pyro']})")

    print("Done.")


if __name__ == "__main__":
    main()
